// Fixed-point coordinate conversion:
// lon in degrees [-180, +180] maps to uint16 [0, 65535]
// lat in degrees [-90, +90]   maps to uint16 [0, 65535]
static inline float globalPtLon(uint16_t v) { return -180.0f + (float)v * (360.0f / 65535.0f); }
static inline float globalPtLat(uint16_t v) { return  -90.0f + (float)v * (180.0f / 65535.0f); }

